"""Original dimensional SVG artwork for the additional reference subjects."""

def register_everyday_icons(icon):
    defs='''<linearGradient id="dice-top" x2=".7" y2="1"><stop stop-color="#fffefa"/><stop offset="1" stop-color="#cfd4d8"/></linearGradient><linearGradient id="dice-left" x2=".9" y2=".3"><stop stop-color="#eceeec"/><stop offset=".8" stop-color="#d9dcdb"/><stop offset="1" stop-color="#b9bfc2"/></linearGradient><linearGradient id="dice-right" x2="1" y2=".4"><stop stop-color="#bec5c7"/><stop offset="1" stop-color="#8b9499"/></linearGradient><radialGradient id="dice-pip" cx="65%" cy="75%"><stop stop-color="#373c40"/><stop offset=".7" stop-color="#24292c"/><stop offset="1" stop-color="#12191d"/></radialGradient>'''
    body='''<path d="M43 82q0-9 12-16l61-35q12-7 24-1l65 33q12 6 12 21l-5 87q-1 16-15 24l-53 32q-13 7-27 0l-60-31q-15-8-16-24Z" fill="url(#dice-right)"/><path d="M43 82q0-9 12-16l61-35q12-7 24-1l65 33q9 5 9 13l-73 43q-9 5-17 1Z" fill="url(#dice-top)"/><path d="m43 82 79 38q9 5 9 16v81q0 14-14 10l-60-31q-15-8-16-24Z" fill="url(#dice-left)"/><path d="m48 82 76 37q11 5 11 19v76" stroke="#fff" stroke-opacity=".38" stroke-width="2.2"/><path d="M49 77q1-5 10-10l58-33q11-6 22-2" stroke="#fff" stroke-opacity=".5" stroke-width="1.1"/>'''
    # Project circular recessed pips into each face with affine transforms.
    for x,y in [(64,117),(105,138),(84,151),(63,164),(104,186)]:
        body+=f'<g transform="matrix(.78 .39 0 1 {x} {y})"><circle cy=".8" r="10.6" fill="#ffffff" opacity=".45"/><circle r="10" fill="url(#dice-pip)"/></g>'
    for x,y in [(159,133),(193,113),(158,178),(191,158)]:
        body+=f'<g transform="matrix(.7 -.4 0 1 {x} {y})"><circle cy=".8" r="10.7" fill="#e8eceb" opacity=".65"/><circle r="10" fill="url(#dice-pip)"/></g>'
    body+='<g transform="matrix(1 .02 .15 .56 128 70)"><circle cy="1" r="14.2" fill="#fff" opacity=".6"/><circle r="13.5" fill="url(#dice-pip)"/></g>'
    icon('dice','Dice','Objects','A softly rounded ivory die with recessed charcoal pips: one on top, five on the front, and four on the side.',defs,body)

    defs='''<radialGradient id="game-controller-shell" cx="35%" cy="20%" r="91%"><stop stop-color="#fbfdfd"/><stop offset=".42" stop-color="#dce4e9"/><stop offset=".72" stop-color="#b8c4ce"/><stop offset="1" stop-color="#6e818e"/></radialGradient><linearGradient id="game-controller-dark" x2=".7" y2="1"><stop stop-color="#626b78"/><stop offset=".4" stop-color="#3d4652"/><stop offset="1" stop-color="#202934"/></linearGradient><radialGradient id="game-controller-stick" cx="32%" cy="22%" r="80%"><stop stop-color="#68717d"/><stop offset=".72" stop-color="#323b46"/><stop offset="1" stop-color="#19222d"/></radialGradient><linearGradient id="game-controller-well" x2=".5" y2="1"><stop stop-color="#8b9caa"/><stop offset="1" stop-color="#f4f8f9"/></linearGradient>'''
    for name,light,dark in [('blue','#99d9ff','#3870bb'),('purple','#ef9cff','#9740b3'),('teal','#99f6e8','#239d96'),('pink','#ff9ed8','#d7368d')]:
        defs+=f'<radialGradient id="game-controller-{name}" cx="30%" cy="23%" r="83%"><stop stop-color="{light}"/><stop offset="1" stop-color="{dark}"/></radialGradient>'
    body='''<path d="M47 79q2-19 28-20h15l5 14m66 0 5-14h15q25 1 28 20" fill="url(#game-controller-dark)"/><path d="M75 66q-25 0-35 27-13 33-19 78-5 32 15 38 17 6 29-15l13-23q6-11 23-11h54q17 0 23 11l13 23q12 21 29 15 20-6 15-38-6-45-19-78-10-27-35-27Z" fill="url(#game-controller-shell)" stroke="#edf3f5" stroke-opacity=".3"/><path d="M32 153q9-70 39-80" stroke="#fff" stroke-opacity=".36" stroke-width="2.2" stroke-linecap="round"/><path d="M212 91q12 30 17 75" stroke="#8798a6" stroke-opacity=".3" stroke-width="1"/>
<path d="M62 89q-5 0-5 5v11H46q-5 0-5 5v7q0 5 5 5h11v11q0 5 5 5h7q5 0 5-5v-11h11q5 0 5-5v-7q0-5-5-5H74V94q0-5-5-5Z" fill="#1a2530" stroke="#99a7b3" stroke-width="1.4"/>
<path d="M62 92q-2 0-2 3v13H47q-3 0-3 3v5q0 3 3 3h13v13q0 3 3 3h5q3 0 3-3v-13h13q3 0 3-3v-5q0-3-3-3H71V95q0-3-3-3Z" fill="url(#game-controller-dark)"/>
<rect x="110" y="108" width="36" height="6" rx="3" fill="#17242c"/><rect x="111" y="109" width="34" height="3" rx="1.5" fill="#57656f"/>'''
    for x,y in [(95,145),(158,145)]:
        body+=f'<circle cx="{x}" cy="{y}" r="19" fill="url(#game-controller-well)"/><circle cx="{x}" cy="{y+1}" r="16.5" fill="#111e29"/><circle cx="{x}" cy="{y}" r="15.2" fill="url(#game-controller-stick)"/><circle cx="{x}" cy="{y}" r="11.5" fill="url(#game-controller-dark)" stroke="#8996a4" stroke-opacity=".3" stroke-width=".5"/>'
    for x,y,c in [(183,89,'blue'),(164,108,'purple'),(202,108,'teal'),(183,127,'pink')]:
        body+=f'<circle cx="{x}" cy="{y+.8}" r="10.5" fill="#405363" opacity=".45"/><circle cx="{x}" cy="{y}" r="9.7" fill="url(#game-controller-{c})" stroke="#23374a" stroke-width=".9"/><path d="M{x-7} {y-2}q1-6 7-6" stroke="#fff" stroke-opacity=".3" stroke-width=".8" stroke-linecap="round"/>'
    icon('game-controller','Game controller','Objects','A pearl-white gamepad with a sculpted grip, charcoal directional pad and twin sticks, and four pastel action buttons.',defs,body)

    defs='''<linearGradient id="home-wall" x2=".8" y2="1"><stop stop-color="#ffe3b9"/><stop offset=".65" stop-color="#eac295"/><stop offset="1" stop-color="#c39772"/></linearGradient><linearGradient id="home-side" x2="1" y2=".4"><stop stop-color="#bb8d6a"/><stop offset="1" stop-color="#d2a47f"/></linearGradient><linearGradient id="home-roof" x2=".8" y2="1"><stop stop-color="#f39153"/><stop offset=".45" stop-color="#df6d39"/><stop offset="1" stop-color="#b74829"/></linearGradient><linearGradient id="home-edge" x2=".8" y2="1"><stop stop-color="#ffb463"/><stop offset=".45" stop-color="#ff943f"/><stop offset="1" stop-color="#df6229"/></linearGradient><linearGradient id="home-glass" x2=".7" y2="1"><stop stop-color="#24465b"/><stop offset=".35" stop-color="#3c6987"/><stop offset="1" stop-color="#23506f"/></linearGradient><linearGradient id="home-handle" x2="1" y2=".2"><stop stop-color="#1e3b4c"/><stop offset=".4" stop-color="#94bad0"/><stop offset="1" stop-color="#3d6b84"/></linearGradient>'''
    body='''<path d="m145 115 65-13v84q0 11-11 16l-48 22-13-12Z" fill="url(#home-side)"/><path d="M44 102 95 46l62 64v104q0 12-15 11l-82-10q-16-2-16-18Z" fill="url(#home-wall)"/><path d="M45 109v85q0 13 14 16" stroke="#fff4d8" stroke-opacity=".32" stroke-width="1.2"/>
<path d="m91 40 69-6q10-1 16 6l53 61q10 13-4 18l-64 17-19-22Z" fill="url(#home-roof)"/><path d="M30 109 85 45q8-9 16-1l64 73q10 13-3 19-8 4-15-5L95 70l-50 57q-10 11-18 2-7-8 3-20Z" fill="url(#home-edge)"/><path d="m34 109 54-60q6-6 12 0l60 68" stroke="#ffd299" stroke-opacity=".27" stroke-width="1.8" stroke-linecap="round"/><path d="m173 128 46-13" stroke="#873f28" stroke-opacity=".3" stroke-width="1.1"/>
<path d="m65 143 24 2q5 0 5 6v68l-32-4v-66q0-7 3-6Z" fill="#8d634d"/><path d="m68 146 20 2q4 0 4 5v65l-27-3v-64q0-5 3-5Z" fill="url(#home-glass)" stroke="#243f4c" stroke-width="1"/>
<path d="m113 146 18 1q6 0 6 6v28q0 5-5 5l-20-2q-4 0-4-5v-27q0-6 5-6Z" fill="#9a6a4b"/><path d="m113 149 18 1q3 0 3 4v25q0 4-3 4l-18-2q-3 0-3-4v-24q0-4 3-4Z" fill="url(#home-glass)" stroke="#284657" stroke-width=".9"/>
<path d="m178 147 12-4q4-1 4 4v25q0 4-4 6l-12 4q-4 1-4-4v-25q0-5 4-6Z" fill="#80573f"/><path d="m179 149 10-3q3-1 3 3v23q0 3-3 4l-10 4q-3 1-3-3v-22q0-5 3-6Z" fill="url(#home-glass)" stroke="#213c4e" stroke-width="1"/>
<rect x="70" y="177" width="4" height="10" rx="2" fill="url(#home-handle)"/><path d="m114 152 16 1" stroke="#a5c8dc" stroke-opacity=".2"/>'''
    icon('home','Home','Objects','A softly bevelled house with a terracotta-orange pitched roof, warm plaster walls, blue inset windows, and a small blue door.',defs,body)
